package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class RandomStringGenerator_ESTest_test12 extends RandomStringGenerator_ESTest_scaffolding {

    /**
     * Verifies that {@link RandomStringGenerator.Builder#withinRange(char[][])} rejects a
     * range pair whose minimum code point is greater than its maximum.
     *
     * <p>The pair {@code {'L', '�'}} maps to minimum code point 76 (the letter 'L')
     * and maximum code point 0 (the NUL character, the default value of an uninitialized
     * char). Since 76 &gt; 0, the builder must throw an {@link IllegalArgumentException}
     * reported by Apache Commons Lang's {@code Validate}.</p>
     */
    @Test(timeout = 4000)
    public void withinRangeRejectsMinGreaterThanMax() throws Throwable {
        RandomStringGenerator.Builder builder = RandomStringGenerator.builder();

        // A single range pair: minimum = 'L' (code point 76), maximum = '�' (code point 0).
        char[] invalidRange = new char[2];
        invalidRange[0] = 'L';
        // invalidRange[1] keeps its default value '�' (code point 0).
        char[][] ranges = new char[1][];
        ranges[0] = invalidRange;

        try {
            builder.withinRange(ranges);
            fail("Expected IllegalArgumentException because minimum code point 76 exceeds maximum code point 0");
        } catch (IllegalArgumentException e) {
            // Message: "Minimum code point 76 is larger than maximum code point 0"
            verifyException("org.apache.commons.lang3.Validate", e);
        }
    }
}
